internal sealed partial class ModernWorkspace {
 internal void PreviewNotes(string path){var note=new NotePage{id="preview-page",title="Idées pour le bot Discord",project="Bot Discord",body="# Prochaine version\nUn endroit pour préparer les prochaines améliorations.\n\n## À préparer\n- [ ] Rédiger le message de bienvenue\n- [x] Définir les commandes prioritaires",updated=DateTime.Now.ToString("o")};store.Value.pages.Add(note);var data=ProjectData.Get(store.Value,"Bot Discord");data.description="Commandes, idées et suivi du développement de mon bot.";selected="Mes notes";Refresh();Preview(path+"-notes.png");OpenProject("Bot Discord");Preview(path+"-projet.png");previewPrefix=path;EditNote(null,"Bot Discord");previewPrefix=null;store.Value.pages.Remove(note);}
 string openProject="",noteQuery="";bool showTrash=false;
 void OpenProject(string name){RecordResume("project",name);openProject=name;selected="Mes projets";Refresh();}
 void Persist(){owner.Save();Refresh();}
 void Notes(StackPanel root){NotesV3(root);}
 void ReadNote(NotePage note){if(!FlushDeskNotes())return;RecordResume("note",note.id);StackPanel body,actions;var w=Dialog(note.title,out body,out actions,760);body.Children.Add(T(String.IsNullOrEmpty(note.project)?"Page personnelle":note.project,11,Muted,new Thickness(0,0,0,18)));var lines=note.body.Replace("\r\n","\n").Split('\n');for(int i=0;i<lines.Length;i++){int index=i;string line=lines[i];if(line.StartsWith("- [ ] ")||line.StartsWith("- [x] ")||line.StartsWith("- [X] ")){var check=new CheckBox{Content=line.Substring(6),IsChecked=line[3]!=' ',Margin=new Thickness(0,5,0,7),Foreground=Ink};check.Click+=delegate{lines[index]=(check.IsChecked==true?"- [x] ":"- [ ] ")+lines[index].Substring(6);note.body=String.Join("\n",lines);note.updated=DateTime.Now.ToString("o");owner.Save();};body.Children.Add(check);}else{bool h1=line.StartsWith("# "),h2=line.StartsWith("## ");string text=h1?line.Substring(2):h2?line.Substring(3):line.StartsWith("- ")?"•  "+line.Substring(2):line;body.Children.Add(T(text,h1?25:h2?19:13,Ink,new Thickness(0,h1||h2?16:3,0,7)));}}bool edit=false;actions.Children.Add(FavoriteButton("note",note.id,note.title));actions.Children.Add(Btn("Modifier",delegate{edit=true;w.DialogResult=true;},true));actions.Children.Add(Btn("Fermer",delegate{w.DialogResult=false;},false,true));ShowWindow(w);Refresh();if(edit)EditNote(note,note.project);}
 void EditNote(NotePage note,string projectName){if(!FlushDeskNotes())return;if(note!=null)RecordResume("note",note.id);StackPanel body,actions;var w=Dialog(note==null?"Nouvelle page":"Modifier la page",out body,out actions,770);var title=new TextBox{Text=note==null?"":note.title,MaxLength=200};Field(body,"Titre de la page",title);var projects=new[]{"Sans projet"}.Concat(owner.AllProjects()).ToArray();var project=Combo(projects,note==null?(String.IsNullOrEmpty(projectName)?"Sans projet":projectName):String.IsNullOrEmpty(note.project)?"Sans projet":note.project);Field(body,"Projet",project);var text=new TextBox{Text=note==null?"":note.body,Height=330,AcceptsReturn=true,AcceptsTab=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,MaxLength=300000};var toolbar=new WrapPanel{Margin=new Thickness(0,0,0,10)};Action<string> insert=delegate(string marker){int start=text.SelectionStart;string prefix=start>0&&text.Text[start-1]!='\n'?Environment.NewLine:"";text.SelectedText=prefix+marker;text.CaretIndex=start+prefix.Length+marker.Length;text.Focus();};toolbar.Children.Add(Btn("Titre",delegate{insert("# ");},false,true));toolbar.Children.Add(Btn("Sous-titre",delegate{insert("## ");},false,true));toolbar.Children.Add(Btn("Liste",delegate{insert("- ");},false,true));toolbar.Children.Add(Btn("☐  À cocher",delegate{insert("- [ ] ");},false,true));body.Children.Add(toolbar);body.Children.Add(text);body.Children.Add(T("Les titres, listes et cases seront mis en forme à l’ouverture de la page.",11,Muted,new Thickness(0,12,0,0)));if(note!=null)actions.Children.Add(Btn("Corbeille",delegate{note.trashed=true;owner.Save();w.DialogResult=false;},false,true));actions.Children.Add(Btn("Annuler",delegate{w.DialogResult=false;},false,true));actions.Children.Add(Btn("Enregistrer",delegate{if(String.IsNullOrWhiteSpace(title.Text)){title.Focus();return;}var n=note??new NotePage{id=Guid.NewGuid().ToString()};n.title=title.Text.Trim();n.project=project.SelectedIndex==0?"":Convert.ToString(project.SelectedItem);n.body=text.Text;n.updated=DateTime.Now.ToString("o");if(note==null)store.Value.pages.Add(n);if(!owner.Save()){if(note==null)store.Value.pages.Remove(n);return;}RecordResume("note",n.id);w.DialogResult=true;},true));ShowWindow(w);Refresh();}
 void EditProject(ProjectSpace existing){StackPanel body,actions;var w=Dialog(existing==null?"Nouveau projet":"À propos du projet",out body,out actions,520);var name=new TextBox{Text=existing==null?"":existing.name,MaxLength=80,IsReadOnly=existing!=null};Field(body,"Nom du projet",name);var description=new TextBox{Text=existing==null?"":existing.description,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,Height=150,MaxLength=10000};Field(body,"Description",description);actions.Children.Add(Btn("Annuler",delegate{w.DialogResult=false;},false,true));actions.Children.Add(Btn("Enregistrer",delegate{if(String.IsNullOrWhiteSpace(name.Text)){name.Focus();return;}var p=existing??ProjectData.Get(store.Value,name.Text.Trim());p.description=description.Text;if(!store.Value.settings.Projects.Contains(p.name))store.Value.settings.Projects.Add(p.name);if(!owner.Save())return;RecordResume("project",p.name);openProject=p.name;selected="Mes projets";w.DialogResult=true;},true));ShowWindow(w);Refresh();}
 void ProjectDetails(StackPanel root){string name=openProject;EnableProjectDrop(root,name);var data=ProjectData.Get(store.Value,name);var top=new WrapPanel{Margin=new Thickness(0,0,0,15)};top.Children.Add(Btn("←  Tous les projets",delegate{Go("Mes projets");},false,true));top.Children.Add(FavoriteButton("project",name,name));top.Children.Add(Btn("À propos",delegate{EditProject(data);},false,true));top.Children.Add(Btn("Apparence du projet",delegate{EditProjectVisual(name);},false,true));top.Children.Add(Btn("Enregistrer comme modèle",delegate{SaveProjectTemplate(name);},false,true));root.Children.Add(top);RenderProjectVisual(root,data);ProjectHub(root,data);if(!String.IsNullOrEmpty(data.description))root.Children.Add(T(data.description,13,Muted,new Thickness(0,0,0,20)));var sections=new System.Collections.Generic.Dictionary<string,UIElement>();var taskBody=new StackPanel();var projectTasks=store.Value.tasks.Where(t=>t.project==name).ToList();taskBody.Children.Add(projectTasks.Count>0?(UIElement)TaskList(projectTasks,0):T("Aucune tâche pour le moment.",13,Muted,new Thickness(0,0,0,14)));taskBody.Children.Add(Btn("+  Ajouter une tâche",delegate{var task=EditTask(new WorkTask{id=Guid.NewGuid().ToString(),title="",project=name,priority="Normale",status="todo",due="",notes=""});if(task!=null){store.Value.tasks.Add(task);if(task.status=="done")Schedule.Complete(store.Value,task);Persist();}},false,true));sections["tasks"]=Card("Tâches du projet",taskBody);var notes=new StackPanel();foreach(var n in store.Value.pages.Where(n=>!n.trashed&&n.project==name).OrderByDescending(n=>n.updated)){var note=n;var b=Btn(n.title,delegate{ReadNote(note);},false,true);b.HorizontalContentAlignment=HorizontalAlignment.Left;notes.Children.Add(b);}notes.Children.Add(Btn("+  Nouvelle page",delegate{EditNote(null,name);},false,true));var noteCard=Card("Pages & notes",notes);noteCard.Margin=new Thickness(0,16,0,0);sections["notes"]=noteCard;var links=new StackPanel();foreach(var l in data.links.ToList()){var link=l;var row=new DockPanel();var remove=Btn("Retirer",delegate{data.links.Remove(link);Persist();},false,true);DockPanel.SetDock(remove,Dock.Right);row.Children.Add(remove);var button=Btn(l.Name,delegate{var pin=store.Value.googlePins.FirstOrDefault(p=>p.url==link.Url);if(pin!=null)OpenGoogleDocument(pin);else Open(link.Url);},false,true);button.HorizontalContentAlignment=HorizontalAlignment.Left;row.Children.Add(button);links.Children.Add(row);}links.Children.Add(Btn("+  Ajouter un lien",delegate{AddProjectLink(data);},false,true));var linkCard=Card("Liens utiles",links);linkCard.Margin=new Thickness(0,16,0,0);sections["links"]=linkCard;var files=new StackPanel();files.Children.Add(DropZone());foreach(var f in data.files.ToList()){var file=f;var row=new DockPanel();var remove=Btn("Retirer",delegate{data.files.Remove(file);Persist();},false,true);DockPanel.SetDock(remove,Dock.Right);row.Children.Add(remove);var button=Btn(f.name+(File.Exists(ProjectData.PathFor(store,file))?"":"  · fichier absent"),delegate{try{string path=ProjectData.PathFor(store,file);if(!File.Exists(path)){MessageBox.Show("Le fichier est absent de ce PC. Les exports JSON ne contiennent pas les pièces jointes.");return;}OpenDocument(path);}catch(Exception ex){MessageBox.Show(ex.Message);}},false,true);button.HorizontalContentAlignment=HorizontalAlignment.Left;PinMenu(button,"file",file.id,file.name);row.Children.Add(button);files.Children.Add(row);}files.Children.Add(Btn("+  Joindre des fichiers",delegate{using(var picker=new System.Windows.Forms.OpenFileDialog{Title="Joindre des fichiers au projet",Multiselect=true})if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK)AttachProjectFiles(name,picker.FileNames);},false,true));files.Children.Add(T("Une copie est conservée dans l’application. Maximum 50 Mo par fichier.",11,Muted,new Thickness(0,10,0,0)));var fileCard=Card("Fichiers du projet",files);fileCard.Margin=new Thickness(0,16,0,0);sections["files"]=fileCard;foreach(var block in data.blocks.Where(b=>b.visible)){var section=(FrameworkElement)sections[block.id];section.Margin=new Thickness(0,0,0,16);root.Children.Add(section);}if(!data.blocks.Any(b=>b.visible))root.Children.Add(T("Tous les blocs sont masqués. Modifiez l’apparence du projet pour les afficher.",12,Muted));}
 void AddProjectLink(ProjectSpace data){StackPanel body,actions;var w=Dialog("Ajouter un lien",out body,out actions,450);var name=new TextBox{MaxLength=120};var url=new TextBox{Text="https://"};Field(body,"Nom",name);Field(body,"Adresse",url);var error=T("",11,Muted);body.Children.Add(error);actions.Children.Add(Btn("Annuler",delegate{w.DialogResult=false;},false,true));actions.Children.Add(Btn("Ajouter",delegate{Uri uri;if(String.IsNullOrWhiteSpace(name.Text)||!Uri.TryCreate(url.Text,UriKind.Absolute,out uri)||(uri.Scheme!="http"&&uri.Scheme!="https")){error.Text="Indiquez un nom et une adresse http ou https.";return;}data.links.Add(new QuickLink{Name=name.Text.Trim(),Url=url.Text.Trim()});owner.Save();w.DialogResult=true;},true));ShowWindow(w);Refresh();}
}
